const out = [];
for (const item of $input.all()) {
  const b = item.json.body || item.json || {};
  const rawPhone = String(b.phone == null ? '' : b.phone);
  const digits = rawPhone.replace(/\D/g, '');
  const phone10 = digits.slice(-10);
  const email = String(b.email == null ? '' : b.email).trim().toLowerCase();
  const fullName = String(b.full_name == null ? '' : b.full_name).trim();
  const skills = String(b.skills == null ? '' : b.skills).trim();
  const city = String(b.city == null ? '' : b.city).trim();
  const expNum = Number(String(b.experience_years == null ? '' : b.experience_years).replace(/[^0-9.]/g, ''));
  const errors = [];
  if (!fullName) errors.push('full_name missing');
  if (!email || !email.includes('@')) errors.push('email invalid');
  if (phone10.length !== 10) errors.push('phone not 10 digits');
  if (!skills) errors.push('skills missing');
  out.push({ json: {
    full_name: fullName,
    email,
    phone: phone10,
    skills,
    experience_years: Number.isFinite(expNum) ? expNum : 0,
    city,
    is_valid: errors.length === 0,
    validation_errors: errors,
    received_at: Date.now(),
  } });
}
return out;

