const tax = $('AI Skill Taxonomy').item.json.output[0].content[0].text;
const norm = $('Normalize & Validate').item.json;
const receivedAt = Number(norm.received_at) || Date.now();
const latencyMs = Date.now() - receivedAt;
const confidence = Number(tax.confidence);
const route = confidence >= 0.85 ? 'auto-write-back' : 'human-review';
return { json: {
  execution_id: $execution.id,
  execution_status: 'success',
  candidate_email: norm.email,
  candidate_phone: norm.phone,
  assigned_taxonomy: tax.assigned_category,
  taxonomy_confidence: confidence,
  keywords: tax.keywords,
  routed_to: route,
  latency_ms: latencyMs,
  logged_at: new Date().toISOString(),
} };
